function singleNumber(nums) {
  const map = {};
  for (let x of nums) {
    map[x] = (map[x] || 0) + 1;
  }
  for (let x in map) {
    if (map[x] === 1) return parseInt(x);
  }
  return -1;
}

optimizedSolution.code:
function singleNumber(nums) {
  let xor = 0;
  for (let i = 0; i < nums.length; i++) {
    xor ^= nums[i];
  }
  return xor;
}
